import { createHash } from "node:crypto";
import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
const literal = (value) => "'" + value.replaceAll("'", "''") + "'";
const names = (await readdir("migrations"))
  .filter((name) => /^\d+_[a-z0-9_]+\.sql$/.test(name))
  .sort();
const sections = [
  `-- ComsFlow v2: run ONLY in project lyeyjfvxmqruszgfrjze SQL Editor.
-- Generated by npm run db:sql; no passwords, keys, users or old data included.
-- Installs schema + private bucket. Does NOT copy Railway data or create an admin.
-- Entire installation rolls back on error. Reruns verify migration checksums.
BEGIN;
SET LOCAL search_path=public,extensions;
SELECT pg_advisory_xact_lock(742917);
DO $target_guard$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND tablename<>'schema_migrations') THEN
  IF to_regclass('public.schema_migrations') IS NULL THEN
   RAISE EXCEPTION 'This is not an empty ComsFlow project. Stop: select the NEW Supabase project.';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.schema_migrations WHERE name='001_initial.sql') THEN
   RAISE EXCEPTION 'Existing tables do not belong to this installer. Stop and verify target.';
  END IF;
 END IF;
END
$target_guard$;
CREATE TABLE IF NOT EXISTS public.schema_migrations(name text PRIMARY KEY,checksum text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.schema_migrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.schema_migrations FROM PUBLIC;
DO $migration_permissions$
DECLARE role_name text;
BEGIN
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON public.schema_migrations FROM %I',role_name); END IF;
 END LOOP;
END
$migration_permissions$;`,
];
for (const name of names) {
  const source = await readFile("migrations/" + name, "utf8"),
    checksum = createHash("sha256").update(source).digest("hex");
  const delimiter = "$source_" + checksum.slice(0, 16) + "$";
  if (source.includes(delimiter))
    throw new Error("Unexpected SQL delimiter collision");
  sections.push(`-- ${name}
DO $install_migration$
DECLARE stored_checksum text;
BEGIN
 SELECT checksum INTO stored_checksum FROM public.schema_migrations WHERE name=${literal(name)};
 IF stored_checksum IS NOT NULL THEN
  IF stored_checksum<>${literal(checksum)} THEN RAISE EXCEPTION 'Migration checksum mismatch: ${name}'; END IF;
 ELSE
  EXECUTE ${delimiter}\n${source}\n${delimiter};
  INSERT INTO public.schema_migrations(name,checksum) VALUES(${literal(name)},${literal(checksum)});
 END IF;
END
$install_migration$;`);
}
sections.push(`-- Storage is configured only when the Supabase storage schema exists.
DO $private_bucket$
BEGIN
 IF to_regclass('storage.buckets') IS NOT NULL THEN
  INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
  VALUES('comsflow-private','comsflow-private',false,52428800,ARRAY['application/pdf','application/octet-stream','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
  ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
 END IF;
END
$private_bucket$;
COMMIT;
SELECT 'ComsFlow schema ready; Railway data has NOT been imported' AS status,count(*) AS migrations FROM public.schema_migrations;
`);
await mkdir("supabase", { recursive: true });
await writeFile("supabase/bootstrap.sql", sections.join("\n\n"));
console.log(
  "Generated supabase/bootstrap.sql with " +
    names.length +
    " checksum-verified migrations.",
);
